{ Relative coordinates are a presentation projection; BlindCoord remains unchanged. }
function DRLPresentationBlindCoord(const aEnglish: AnsiString; const aWhere: TCoord2D): AnsiString;
var iExpected, iVertical, iHorizontal: AnsiString;
begin
  iExpected := '[';
  if aWhere.y > 0 then iExpected += IntToStr(aWhere.y) + 's';
  if aWhere.y < 0 then iExpected += IntToStr(-Int64(aWhere.y)) + 'n';
  if aWhere.x > 0 then iExpected += IntToStr(aWhere.x) + 'e';
  if aWhere.x < 0 then iExpected += IntToStr(-Int64(aWhere.x)) + 'w';
  if (aWhere.x = 0) and (aWhere.y = 0) then iExpected += 'here';
  iExpected += ']';
  if aEnglish <> iExpected then Exit(aEnglish);
  if (aWhere.x = 0) and (aWhere.y = 0) then Exit(DRLText('entity.coordinate.here', '[here]'));
  iVertical := '';
  iHorizontal := '';
  if aWhere.y > 0 then iVertical := DRLText('entity.coordinate.south', '{{distance}}s', [DRLIntegerParam('distance', Int64(aWhere.y))]);
  if aWhere.y < 0 then iVertical := DRLText('entity.coordinate.north', '{{distance}}n', [DRLIntegerParam('distance', -Int64(aWhere.y))]);
  if aWhere.x > 0 then iHorizontal := DRLText('entity.coordinate.east', '{{distance}}e', [DRLIntegerParam('distance', Int64(aWhere.x))]);
  if aWhere.x < 0 then iHorizontal := DRLText('entity.coordinate.west', '{{distance}}w', [DRLIntegerParam('distance', -Int64(aWhere.x))]);
  Exit(DRLText('entity.coordinate.relative', '[{{vertical}}{{horizontal}}]', [DRLStringParam('vertical', iVertical), DRLStringParam('horizontal', iHorizontal)]));
end;

