function TTraits.GetHistoryIDs: TBytes;
var i, count: SizeInt;
begin
  SetLength(Result, High(FOrder));
  count := 0;
  for i := 1 to High(FOrder) do
    if (FOrder[i] > 0) and (FOrder[i] <= High(FValues)) then
    begin
      Result[count] := FOrder[i];
      Inc(count);
    end;
  SetLength(Result, count);
end;

